const ticket = $('Loop Over Items').item.json;

if (!$json.hasOwnProperty('Vendor Name')) {
  const line = `🔧 ${ticket['Ticket ID']} | ${ticket['Category']} | ${ticket['Address']}\n` +
               `   Issue: ${ticket['Description']}\n` +
               `   ⚠️ কোনো Active vendor পাওয়া যায়নি এই category-তে!\n`;
  return [{ json: { line } }];
}

const vendor = $json;
const baseUrl = 'https://782-1285.n8n-2.dignityhost.com/form-test/f45812b8-19f1-4cf1-85c8-acff515f09bf';

const paramObj = {
  'Ticket ID': ticket['Ticket ID'],
  'Vendor Name': vendor['Vendor Name'],
  'Vendor Email': vendor['Email']
};

const queryString = Object.entries(paramObj)
  .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
  .join('&');

const assignLink = `${baseUrl}?${queryString}`;

const line = `🔧 ${ticket['Ticket ID']} | ${ticket['Category']} | ${ticket['Unit/Property Address']}\n` +
             `   Issue: ${ticket['Description']}\n` +
             `   Suggested: ${vendor['Vendor Name']} (${vendor['Phone']})\n` +
             `   👉 Assign: ${assignLink}\n`;

return [{ json: { line } }];

const allItems = $input.all();

if (allItems.length === 0) {
  return [{ json: { message: null } }];
}

const allLines = allItems.map(item => item.json.line).join('\n');
const message = `📋 Today's queued maintenance requests (${allItems.length}):\n\n${allLines}`;

return [{ json: { message } }];

