const tickets = $input.all().map(item => item.json);
const total = tickets.length;

function countBy(field) {
  const counts = {};
  for (const t of tickets) {
    const key = t[field] || 'Unknown';
    counts[key] = (counts[key] || 0) + 1;
  }
  return counts;
}

const byUrgency = countBy('Urgency');
const byCategory = countBy('Category');
const byStatus = countBy('Status');

function rowsHtml(counts) {
  return Object.entries(counts)
    .map(([k, v]) => `
      <tr>
        <td style="padding:8px 14px;border:1px solid #e5e7eb;">${k}</td>
        <td style="padding:8px 14px;border:1px solid #e5e7eb;text-align:center;">${v}</td>
      </tr>`)
    .join('');
}

function tableHtml(title, counts) {
  return `
    <h3 style="color:#111827;font-family:Arial,sans-serif;margin-top:24px;">${title}</h3>
    <table style="border-collapse:collapse;width:100%;font-family:Arial,sans-serif;font-size:14px;">
      <tr style="background:#f3f4f6;">
        <th style="padding:8px 14px;border:1px solid #e5e7eb;text-align:left;">${title.replace('By ', '')}</th>
        <th style="padding:8px 14px;border:1px solid #e5e7eb;">Count</th>
      </tr>
      ${rowsHtml(counts)}
    </table>`;
}

const html = `
<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;padding:20px;">
  <h2 style="color:#1a56db;margin-bottom:4px;">Weekly Maintenance Report</h2>
  <p style="color:#6b7280;font-size:13px;margin-top:0;">
  ${$now.minus({days:7}).toFormat('MMM d')} - ${$now.toFormat('MMM d, yyyy')}
</p>
  <p style="font-size:16px;">Total tickets this week: <strong>${total}</strong></p>

  ${tableHtml('By Urgency', byUrgency)}
  ${tableHtml('By Category', byCategory)}
  ${tableHtml('By Status', byStatus)}

  <p style="color:#9ca3af;font-size:12px;margin-top:32px;border-top:1px solid #e5e7eb;padding-top:12px;">
    Horizon Prime Realty — Automated Weekly Report
  </p>
</div>
`;

return [{ json: { html } }];

